#!/bin/bash
# usage: tests/x86_i2d_kernel.sh [NV] -> kernels x_sf_i2d (ours: lib/fp/f64/float.c under config/x86_m32, __floatdidf) and x_crt_i2d (compiler-rt floatdidf) in
# crates/target/llrm-x86-m32/vsgcc/kernels/ for harness.py. Input: a 64-bit value shifted right by 0..63 (all magnitudes, both signs).
set -e
cd "$(dirname "$0")/.."
NV=${1:-400}; SF_CFG=$(sed -E 's/\buint(32|64)_t\b/sfu\1/g' config/x86_m32/config.h); export SF_CFG
K=$(cd ../../crates/target/llrm-x86-m32/vsgcc/kernels && pwd); T=$(mktemp -d); trap 'rm -r $T' EXIT
CRT=${COMPILER_RT:-$HOME/scratch/llvm-src-m16/compiler-rt/lib/builtins}
cc -O2 -ffp-contract=off tests/gen_vectors64.c -o $T/gen && $T/gen $NV > $T/vectors.h
printf '#include <stdio.h>\nvoid report(long v) { printf("%%ld\\n", v); }\n' > $T/rep.c
TYPES='typedef unsigned char sfu8; typedef signed char sfi8; typedef short sfi16; typedef unsigned short sfu16; typedef int sfi32; typedef unsigned int sfu32; typedef unsigned long long sfu64; typedef long long sfi64;'
emit() { n=$1; mkdir -p $K/$n
  { echo 'extern void report(long value);'; cat $T/body.c; sed 's/uint32_t/sfu32/' $T/vectors.h
    echo "long bench_$n(long n) { long i; sfu32 acc = 0; for (i = 0; i < n; ++i) { const sfu32 *v = V[i % NV]; sfi64 x = (sfi64)(((sfu64)v[0] << 32) | v[1]) >> (v[2] & 63); sfu64 r = ($2); acc += (sfu32)r ^ (sfu32)(r >> 32); } return (long)acc; }"
    echo "int main(void) { report(bench_$n($NV)); return 0; }"; } > $K/$n/$n.c
  gcc -m32 -O0 -w $K/$n/$n.c $T/rep.c -o $T/ref && $T/ref > $K/$n/$n.out; }
{ echo "/* x_sf_i2d: runtime/compiler-rt __floatdidf (f64/float.c as linked) over $NV vectors; generated by tests/x86_i2d_kernel.sh */"; echo "$TYPES"
  echo '#define UINT32_C(x) x##u'; echo '#define UINT64_C(x) x##ull'; echo '#define INT32_MAX 2147483647'; echo '#define INT32_MIN (-2147483647-1)'; echo '#define UINT32_MAX 4294967295u'; echo '#define INT64_MAX 9223372036854775807ll'; echo '#define UINT64_MAX 18446744073709551615ull'
  for f in include/softfloat.h include/sf_helpers.h lib/fp/f64/float.c lib/fp/f64/pack.c; do
    python3 tests/flatten.py $f | sed -E '/#include <(stdint|stddef|limits)\.h>/d; /#include "(softfloat|sf_helpers|sf_int)\.h"/d; s/\buint8_t\b/sfu8/g; s/\bint8_t\b/sfi8/g; s/\buint16_t\b/sfu16/g; s/\bint16_t\b/sfi16/g; s/\buint32_t\b/sfu32/g; s/\bint32_t\b/sfi32/g; s/\buint64_t\b/sfu64/g; s/\bint64_t\b/sfi64/g'
  done | awk 'BEGIN{print "#define SF_INTABI 1"; if (ENVIRON["SF_CFG"]) print ENVIRON["SF_CFG"]} {print}'; } > $T/body.c
emit x_sf_i2d "__floatdidf(x)"
{ gcc -m32 -E -P -I$CRT $CRT/floatdidf.c | sed '/Qcomplex/d; /__alias__/d'; echo 'int __fe_raise_inexact(void) { return 0; }'; echo 'int __fe_getround(void) { return 0; }'
  echo "$TYPES"; } > $T/body.c
emit x_crt_i2d "({ union { double d; sfu64 u; } r; r.d = __floatdidf(x); r.u; })"
echo "wrote $K/x_{sf,crt}_i2d"
